 public static class ShellIcons {
  [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct Info {public IntPtr Icon;public int Index;public uint Attributes;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=260)]public string Name;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=80)]public string Type;}
  [DllImport("shell32.dll",CharSet=CharSet.Unicode)]static extern IntPtr SHGetFileInfo(string path,uint attributes,out Info info,uint size,uint flags);
  [DllImport("user32.dll")]static extern bool DestroyIcon(IntPtr icon);
  [DllImport("shlwapi.dll",CharSet=CharSet.Unicode)]static extern uint AssocQueryString(uint flags,uint type,string assoc,string extra,System.Text.StringBuilder output,ref uint length);
  static readonly Dictionary<string,ImageSource> cache=new Dictionary<string,ImageSource>(StringComparer.OrdinalIgnoreCase);
  public static ImageSource Get(string path,bool folder){if(String.IsNullOrWhiteSpace(path))path="application.exe";string ext=Path.GetExtension(path);bool individual=folder||new[]{".exe",".lnk",".url",".ico"}.Contains(ext.ToLowerInvariant());string key=individual?path:ext;lock(cache){ImageSource image;if(cache.TryGetValue(key,out image))return image;Info info;string lookup=individual?path:"file"+ext;if(!folder&&new[]{".jpg",".jpeg",".png",".bmp",".gif",".webp",".heic"}.Contains(ext.ToLowerInvariant())){uint size=2048;var output=new System.Text.StringBuilder((int)size);if(AssocQueryString(0,2,ext,null,output,ref size)==0&&File.Exists(output.ToString())){lookup=output.ToString();individual=true;}}bool exists=File.Exists(lookup)||Directory.Exists(lookup);uint flags=0x100;if(!exists||!individual)flags|=0x10;SHGetFileInfo(lookup,folder?0x10u:0x80u,out info,(uint)Marshal.SizeOf(typeof(Info)),flags);if(info.Icon==IntPtr.Zero)return null;try{image=System.Windows.Interop.Imaging.CreateBitmapSourceFromHIcon(info.Icon,Int32Rect.Empty,BitmapSizeOptions.FromWidthAndHeight(48,48));image.Freeze();if(cache.Count>512)cache.Clear();cache[key]=image;return image;}finally{DestroyIcon(info.Icon);}}}
 }
