  static string IconFile(string value){if(String.IsNullOrEmpty(value))return null;value=value.Trim();if(value.StartsWith("\"")){int end=value.IndexOf('"',1);return end>0?value.Substring(1,end-1):null;}int comma=value.LastIndexOf(',');return comma>=0?value.Substring(0,comma).Trim():value;}
  static string LaunchCandidate(string value){var path=IconFile(value);return path!=null&&path.EndsWith(".exe",StringComparison.OrdinalIgnoreCase)&&File.Exists(path)&&!Catalog.Helper(path)?path:null;}
  void UninstallSelected(){var item=Find<DataGrid>("AppList").SelectedItem as InstalledApp;if(item==null)return;if(String.IsNullOrWhiteSpace(item.UninstallCommand)){Process.Start(new ProcessStartInfo("ms-settings:appsfeatures"){UseShellExecute=true});return;}if(!Dialog("Gỡ ứng dụng", "Mở trình gỡ cài đặt của "+item.Name+"? Windows hoặc ứng dụng sẽ hướng dẫn các bước tiếp theo.",true))return;string command=item.UninstallCommand.Trim();string exe,args;if(command.StartsWith("\"")){int end=command.IndexOf('"',1);if(end<0)throw new IOException("Lệnh gỡ không hợp lệ.");exe=command.Substring(1,end-1);args=command.Substring(end+1).Trim();}else{int end=command.IndexOf(".exe",StringComparison.OrdinalIgnoreCase);if(end>=0){exe=command.Substring(0,end+4);args=command.Substring(end+4).Trim();}else{int split=command.IndexOf(' ');exe=split<0?command:command.Substring(0,split);args=split<0?"":command.Substring(split+1);}}if(Path.GetFileName(exe).Equals("msiexec.exe",StringComparison.OrdinalIgnoreCase))args=System.Text.RegularExpressions.Regex.Replace(args,@"/I(?=\s|\{)","/X",System.Text.RegularExpressions.RegexOptions.IgnoreCase);Process.Start(new ProcessStartInfo(exe,args){UseShellExecute=true});}
