  void SetupTaskFilters(){var pageGrid=Find<Grid>("TransfersPage");var header=(StackPanel)pageGrid.Children[0];var filters=new WrapPanel {Margin=new Thickness(0,0,0,16)};foreach(string value in new[]{"Tất cả","Đang chạy","Hoàn tất","Lỗi / đã hủy"}){string f=value;var b=new Button {Content=value,Padding=new Thickness(12,7,12,7)};b.Click+=(s,e)=>{jobFilter=f;UpdateJobs();};filters.Children.Add(b);}var groups=new ComboBox {Width=200};foreach(string g in new[]{"Mọi loại tác vụ","Sao chép / di chuyển","Phân loại","Nén / giải nén","Đổi tên","Thùng rác","Hoàn tác"})groups.Items.Add(g);w.RegisterName("JobGroupFilter",groups);groups.SelectedIndex=0;groups.SelectionChanged+=(s,e)=>UpdateJobs();filters.Children.Add(groups);header.Children.Add(filters);var summary=Text("Chưa có tác vụ.",12,"#9CAEC7");w.RegisterName("JobSummary",summary);summary.Margin=new Thickness(0,0,0,12);header.Children.Add(summary);var help=Text("Chọn một tác vụ để tạm dừng / tiếp tục hoặc hủy. Hoàn tác chỉ áp dụng cho di chuyển.",11,"#9CAEC7");help.Margin=new Thickness(0,0,0,12);header.Children.Add(help);}
  void UpdateJobs(){if(w==null)return;var filter=Find<ComboBox>("JobGroupFilter");string group=filter==null||filter.SelectedIndex<=0?null:filter.SelectedItem.ToString();Find<ListBox>("Jobs").ItemsSource=jobs.Where(j=>(group==null||j.Group==group)&&(jobFilter=="Tất cả"||jobFilter=="Đang chạy"&&!j.Finished||jobFilter=="Hoàn tất"&&j.Status=="Hoàn tất"||jobFilter=="Lỗi / đã hủy"&&(j.Status.StartsWith("Lỗi")||j.Status=="Đã hủy"))).OrderByDescending(j=>j.Started).ToList();if(Find<TextBlock>("JobSummary")!=null)Find<TextBlock>("JobSummary").Text=jobs.Count(j=>!j.Finished)+" đang chạy / chờ · "+jobs.Count(j=>j.Status=="Hoàn tất")+" hoàn tất · "+jobs.Count(j=>j.Status.StartsWith("Lỗi"))+" lỗi";}
  void SetupStorageGuide(){var host=(StackPanel)Find<ScrollViewer>("StoragePage").Content;var guide=Text("01  Chọn thư mục và phân tích  →  02  Xem loại file, thư mục lớn  →  03  Kiểm tra trùng nội dung nếu cần\nKhông tự xóa dữ liệu. Nhấp đúp file trong kết quả để mở vị trí.",12,"#9CAEC7");guide.Margin=new Thickness(0,0,0,22);host.Children.Insert(2,guide);var actions=(WrapPanel)Find<Button>("Analyze").Parent;var old=new Button {Content="Lâu không sửa (> 6 tháng)"};old.Click+=(s,e)=>Find<DataGrid>("StorageFiles").ItemsSource=storageSnapshot.Where(f=>f.Modified<DateTime.Now.AddMonths(-6)).OrderByDescending(f=>f.Bytes).ToList();actions.Children.Add(old);Find<DataGrid>("StorageFiles").MouseDoubleClick+=(s,e)=>{var item=Find<DataGrid>("StorageFiles").SelectedItem as Entry;if(item!=null)OpenFolder(Path.GetDirectoryName(item.Path));};}
  void SetupOrganizeGuide(){var host=(StackPanel)Find<ScrollViewer>("OrganizePage").Content;var guide=Text("CHUYỂN FILE:  1. Chọn nguồn / đích   →   2. Bật nhóm cần chia   →   3. Xem trước   →   4. Chuyển ngay hoặc theo dõi\nẢnh → Ảnh · Word / Excel / PowerPoint → Office · Game → chỉ lập danh mục, không tách EXE khỏi tài nguyên.",12,"#9CAEC7");guide.Margin=new Thickness(0,0,0,22);host.Children.Insert(2,guide);}
  void InstallSmoothScroll(FrameworkElement root){root.AddHandler(UIElement.PreviewMouseWheelEvent,new MouseWheelEventHandler((s,e)=>{DependencyObject node=e.OriginalSource as DependencyObject;while(node!=null&&!(node is ScrollViewer)){node=node is Visual?VisualTreeHelper.GetParent(node):LogicalTreeHelper.GetParent(node);}var view=node as ScrollViewer;if(view==null||view.ScrollableHeight<=0)return;SmoothScrolling.Move(view,-e.Delta*0.7,state.Settings.Motion);e.Handled=true;}),true);}
 }
 public static class SmoothScrolling {
  class Motion {public double Start,Target;public DateTime Time;public DispatcherTimer Timer;}
  static readonly Dictionary<ScrollViewer,Motion> active=new Dictionary<ScrollViewer,Motion>();
  public static void Move(ScrollViewer viewer,double delta,bool animate){Motion old;double start=active.TryGetValue(viewer,out old)?old.Target:viewer.VerticalOffset;To(viewer,Math.Max(0,Math.Min(viewer.ScrollableHeight,start+delta)),animate);}
  public static void To(ScrollViewer viewer,double target,bool animate){Motion old;if(active.TryGetValue(viewer,out old))old.Timer.Stop();if(!animate){viewer.ScrollToVerticalOffset(target);active.Remove(viewer);return;}var m=new Motion {Start=viewer.VerticalOffset,Target=target,Time=DateTime.UtcNow,Timer=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(16)}};active[viewer]=m;m.Timer.Tick+=(s,e)=>{double t=Math.Min(1,(DateTime.UtcNow-m.Time).TotalMilliseconds/150);double ease=1-Math.Pow(1-t,3);viewer.ScrollToVerticalOffset(m.Start+(m.Target-m.Start)*ease);if(t>=1){m.Timer.Stop();active.Remove(viewer);}};m.Timer.Start();}
 }
}


